{
  "items": [
    {
      "title": "Roper Center – Uruguay Public Opinion Surveys, 1960s",
      "url_or_doi": "https://ropercenter.cornell.edu/featured-collections/uruguay",
      "justification": "One of the most directly relevant sources. The Roper Center at Cornell University catalogs 19 public opinion datasets from Uruguay during the 1960s. Topics include political preferences, voting intentions, political parties, constitutional reform, government evaluation, foreign relations, strikes, and protests. The collection includes historical surveys conducted by organizations such as Gallup Uruguay. Particularly useful for studying political attitudes and electoral behavior during the decade. Access to individual datasets may require institutional membership."
    },
    {
      "title": "Roper Center – Latin American Data Bank",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-data-bank",
      "justification": "A historical collection of Latin American public opinion surveys, including data from Uruguay. The Uruguay collection contains surveys covering political preferences, elections, government performance, economic conditions, and social mobilization. Researchers can identify historical surveys from the 1960s and compare Uruguayan political attitudes with those in other Latin American countries. Some datasets may require institutional access."
    },
    {
      "title": "Roper Center – Latin American USIA Reports, 1950s–1970s",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "An especially valuable historical collection containing contemporary survey reports from Uruguay during the early 1960s. It includes studies of attitudes toward the United States, the Soviet Union, Fidel Castro, the Cuban Revolution, and the Alliance for Progress. These reports provide evidence about Cold War political attitudes and ideological orientations among Uruguayans. The collection includes both Uruguay-specific research and comparative Latin American surveys. The reports are particularly useful as historical survey evidence, although respondent-level microdata availability must be checked."
    },
    {
      "title": "Montevidean Attitudes toward the US Before and After President Eisenhower's Visit (1960)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A historical public opinion study conducted in Montevideo in 1960, cataloged as USIA Report R256. It examines attitudes toward the United States around President Dwight Eisenhower's visit. Relevant for analyzing political perceptions, foreign-policy orientations, and the influence of international political events on Uruguayan public opinion. The report provides a contemporary snapshot of attitudes at the beginning of the 1960s."
    },
    {
      "title": "Encuesta sobre la Visita al Uruguay del Presidente Eisenhower (1960)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A public opinion survey conducted in Uruguay on March 2–3, 1960, before President Eisenhower's visit, cataloged as USIA Report R142. It offers historical evidence about Uruguayan perceptions of American leadership and international relations. Particularly useful for researchers examining political attitudes toward the United States during the Cold War. The archival listing identifies the survey report, but the availability of original respondent-level data requires verification."
    },
    {
      "title": "The Impact of Castro upon Latin American Public Opinion: Survey Indicators from Seven Countries (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative survey report dated February 1, 1961, cataloged as USIA Report R258. It includes Uruguay alongside Argentina, Brazil, Colombia, Mexico, Peru, and Venezuela. The study investigates public attitudes toward Fidel Castro and the Cuban Revolution. It is highly relevant for understanding ideological divisions, perceptions of revolutionary movements, and Cold War political attitudes in Uruguay during the early 1960s."
    },
    {
      "title": "The Climate of Opinion in Latin America for the Alliance for Progress (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative public opinion study published on August 1, 1961, cataloged as USIA Report R261. Uruguay is one of seven Latin American countries included. The study examines attitudes toward the Alliance for Progress, a major United States development initiative during the Kennedy administration. It provides historical evidence about political orientations, perceptions of international assistance, and public reactions to Cold War development policies."
    },
    {
      "title": "Public Opinion toward the Alliance for Progress in Bogota and Other Latin American Cities (1961)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative public opinion report dated December 1, 1961, cataloged as USIA Report R262. It includes Uruguay, Argentina, Brazil, and Colombia. The report investigates urban attitudes toward the Alliance for Progress. Particularly useful for comparing Uruguayan public opinion with attitudes in other South American cities during the early 1960s."
    },
    {
      "title": "Castro's Standing in Five Latin American Cities during 1961 (1962)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative political opinion report dated March 1, 1962, cataloged as USIA Report R211. It includes Uruguay alongside Argentina, Colombia, Brazil, and Mexico. The study examines perceptions of Fidel Castro in Latin American cities during 1961. It is relevant for investigating political ideology, reactions to the Cuban Revolution, and international political attitudes among urban Uruguayans."
    },
    {
      "title": "The Economic and Political Climate of Opinion in Latin America and Attitudes toward the Alliance for Progress (1963)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A comparative public opinion study dated June 25, 1963, cataloged as USIA Report R218. It covers Uruguay and six other Latin American countries. The research examines economic and political perceptions alongside attitudes toward the Alliance for Progress. Particularly valuable for connecting political attitudes with economic dissatisfaction, perceptions of development, and international relations during Uruguay's economic and political difficulties in the 1960s."
    },
    {
      "title": "The Economic and Political Climate of Opinion in Latin America – Economic Subgroup Breakdowns (1964)",
      "url_or_doi": "https://ropercenter.cornell.edu/latin-american-usia-reports",
      "justification": "A supplementary report dated April 30, 1964, cataloged as USIA Report R223. It provides breakdowns of political and economic attitudes by economic subgroup within urban samples from seven Latin American countries, including Uruguay. Especially relevant for examining differences in political attitudes across socioeconomic groups during the 1960s. It may help investigate relationships between economic position, political dissatisfaction, and perceptions of international development initiatives."
    },
    {
      "title": "World Handbook of Political and Social Indicators III: 1948–1982",
      "url_or_doi": "https://www.icpsr.umich.edu/web/ICPSR/studies/7761",
      "justification": "A historical cross-national dataset archived by the Inter-university Consortium for Political and Social Research (ICPSR), study 7761. It includes political and socioeconomic indicators covering the 1960s, with reference years including 1960 and 1965. Variables include voter turnout, registered voters, political parties, legislative representation, political and civil rights, inequality, and socioeconomic characteristics. It is particularly useful for studying aggregate electoral behavior and the political environment in Uruguay. Unlike opinion surveys, it primarily provides country-level indicators rather than individual political attitudes."
    },
    {
      "title": "World Handbook of Political and Social Indicators I and A Cross-Polity Survey: Merged Data, 1961–1963",
      "url_or_doi": "https://www.icpsr.umich.edu/web/ICPSR/studies/5023/export",
      "justification": "A historical comparative political dataset archived by ICPSR, study 5023, explicitly including Uruguay. The merged dataset covers political and social characteristics around 1961–1963. It is useful for examining Uruguay's political institutions and broader political context in comparison with other countries during the early 1960s. It complements individual-level opinion surveys by providing aggregate contextual information."
    }
  ]
}
